using System;using System.Reflection;using System.Windows.Forms;
class StartupTest{[STAThread]static void Main(string[] args){var assembly=Assembly.LoadFrom(args[0]);var factory=assembly.GetType("SetupForm").GetMethod("CreateStartupForm",BindingFlags.Static|BindingFlags.NonPublic);using(var form=(Form)factory.Invoke(null,new object[]{new[]{"/settings"}})){if(form.GetType().Name!="SoundSettingsForm")throw new Exception("Settings launch returned installer");if(!form.Text.Contains("v"+assembly.GetName().Version.ToString(3)))throw new Exception("Settings version missing");bool uninstall=false;foreach(Control c in form.Controls)if(c is Button && c.Text=="Uninstall...")uninstall=true;if(!uninstall)throw new Exception("Settings uninstall missing");form.Show();Application.DoEvents();int visible=0;foreach(Form window in Application.OpenForms){if(window.Visible){visible++;if(window.GetType().Name!="SoundSettingsForm")throw new Exception("Installer is visible");}}if(visible!=1)throw new Exception("Expected exactly one visible window");form.Close();}using(var form=(Form)factory.Invoke(null,new object[]{new string[0]})){if(!form.Text.Contains("v"+assembly.GetName().Version.ToString(3)))throw new Exception("Setup version missing");if(form.GetType().Name!="SetupForm")throw new Exception("Installer entry changed");bool close=false;foreach(Control c in form.Controls){if(c is Button && c.Text=="Sound Settings")throw new Exception("Sound Settings is still exposed in installer");if(c is Button && c.Text=="Close")close=true;}if(!close)throw new Exception("Installer Close button missing");}using(var options=(Form)Activator.CreateInstance(assembly.GetType("UninstallOptionsForm"))){var property=options.GetType().GetProperty("DeleteAll");if((bool)property.GetValue(options,null))throw new Exception("Preserve should be the default");foreach(Control c in options.Controls)if(c is RadioButton && c.Text.StartsWith("Remove all"))((RadioButton)c).Checked=true;if(!(bool)property.GetValue(options,null))throw new Exception("Remove-all choice failed");}
Console.WriteLine("PASS: /settings shows only Sound Settings; default entry remains installer.");}}
